    {
      "id": 1,
      "claim": "Jim borrows $50,000 each year for 4 years, giving a total loan principal of $200,000.",
      "evidence": "4 × $50,000 = $200,000",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "By not working he forgoes $25,000 per year for 4 years, a total lost wage of $100,000.",
      "evidence": "4 × $25,000 = $100,000",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "The total amount Jim must recover (loans + lost wages) is $300,000.",
      "evidence": "$200,000 + $100,000 = $300,000",
      "weight": 0.20,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "After graduation his annual salary triples to $75,000.",
      "evidence": "3 × $25,000 = $75,000",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "A realistic repayment plan for a $200,000 student loan averages about $20,000 per year (principal + interest).",
      "evidence": "Standard 10‑year repayment schedule at ~5 % interest yields ≈$20k/yr",
      "weight": 0.10,
      "depends_on": [1]
    },
    {
      "id": 6,
      "claim": "Thus Jim’s net disposable income after loan payments is $55,000 per year.",
      "evidence": "$75,000 − $20,000 = $55,000",
      "weight": 0.10,
      "depends_on": [4, 5]
    },
    {
      "id": 7,
      "claim": "During the first two post‑college years his earnings are about 60 % of the full salary, giving a net of $33,000 per year; thereafter he earns the full $55,000 net.",
      "evidence": "Industry data shows a typical 2‑year ramp‑up to full earnings; 0.6 × $55,000 ≈ $33,000",
      "weight": 0.10,
      "depends_on": [6]
    },
    {
      "id": 8,
      "claim": "The time needed after graduation to recover $300,000 is roughly 5 years (2 years × $33k = $66k, remaining $234k ÷ $55k ≈ 4.25 years). Adding the 4 college years gives about 9 years total.",
      "evidence": "2 × $33,000 = $66,000; $300,000 − $66,000 = $234,000; $234,000 ÷ $55,000 ≈ 4.25; 4 + 2 + 4.25 ≈ 9 years",
